/**
 * Hands the thread back to the page every ~30ms. Decoding a big scan takes
 * seconds; without this the tab would freeze for all of them, spinner and
 * scrolling included.
 */
function makeYielder(): () => Promise<void> {
    let last = Date.now();
    return async () => {
        if (Date.now() - last < 30) return;
        await new Promise<void>((r) => setTimeout(r, 0));
        last = Date.now();
    };
}

